/**
 * Menu bundled like the legacy application (mdiMain): groups, sub-menus, captions and order come from the legacy menu.
 * A node with a `route` is migrated; a node with `legacyForm` is a legacy screen that is not migrated yet.
 * `positions` are legacy USRAccess positions; a node is visible when the user has any of them (or it has none).
 * The tree is generated by tools/build-menu.ps1, whose JSON writes one-element lists as plain values, so both shapes are accepted.
 */
export interface MenuNode {
  label: string
  route?: string
  positions?: number | number[]
  legacyForm?: string
  children?: MenuNode | MenuNode[]
}

export interface VisibleNode { label: string; route?: string; legacyForm?: string; children?: VisibleNode[] }

const list = <T,>(v: T | T[] | undefined): T[] => (v === undefined ? [] : Array.isArray(v) ? v : [v])

/** Keeps the nodes the user may see. Legacy (not migrated) entries are kept only when `showLegacy` is true; groups without visible children disappear. */
export function visibleMenu(nodes: MenuNode[], can: (position: number) => boolean, showLegacy: boolean): VisibleNode[] {
  const out: VisibleNode[] = []
  for (const n of nodes) {
    if (n.children !== undefined) {
      const children = visibleMenu(list(n.children), can, showLegacy)
      if (children.length > 0) out.push({ label: n.label, children })
      continue
    }
    const positions = list(n.positions)
    if (positions.length > 0 && !positions.some(can)) continue
    if (n.route) out.push({ label: n.label, route: n.route })
    else if (showLegacy) out.push({ label: n.label, legacyForm: n.legacyForm ?? '' })
  }
  return out
}

/** True when the route belongs to this node or any node below it (used to open the group that holds the current page). */
export function containsRoute(node: VisibleNode, pathname: string): boolean {
  return node.route === pathname || (node.children?.some((c) => containsRoute(c, pathname)) ?? false)
}
